		return nil // everything staged is work the inherited checkpoints hold
	}

	_, findSessionsSpan := perf.Start(ctx, "find_sessions_for_worktree")
	worktreePath, err := paths.WorktreeRoot(ctx)
	if err != nil {
		findSessionsSpan.RecordError(err)
		findSessionsSpan.End()
		return nil
	}

	// Union of worktree matching and identity matching (the committing
	// process's ancestry) — see findSessionsForCommitLinking; neither
	// suppresses the other. We match by worktree (not BaseCommit) because
	// the user may have made intermediate commits without entering new
	// prompts, causing HEAD to diverge
	sessions, err := s.findSessionsForCommitLinking(ctx, worktreePath)
	if err != nil || len(sessions) == 0 {
		findSessionsSpan.RecordError(err)
		findSessionsSpan.End()
		// No active sessions or error listing - silently skip (hooks must be resilient)
		logging.Debug(logCtx, "prepare-commit-msg: no active sessions",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
		)
		return nil
	}
	findSessionsSpan.End()

	// Fast path: skip content detection for mid-turn agent commits. A session
	// whose agent provably did not make this commit is left to content
	// detection below.
	provenance := newCommitProvenance(ctx, sessions)
	if s.tryAgentCommitFastPath(ctx, commitMsgFile, provenance.withoutForeign(sessions), source, inherited) {
		return nil
	}

	// Check if any session has new content to condense
	_, filterSessionsSpan := perf.Start(ctx, "filter_sessions_with_content")
	sessionsWithContent := s.filterSessionsWithNewContent(ctx, repo, sessions, redone, provenance)
	filterSessionsSpan.End()

	if len(sessionsWithContent) == 0 {
		// No new content — no trailer needed
		logging.Debug(logCtx, "prepare-commit-msg: no content to link",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
			slog.Int("sessions_found", len(sessions)),
		)
		return nil
	}

	// Read current commit message
	_, readCommitMessageSpan := perf.Start(ctx, "read_commit_message")
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		readCommitMessageSpan.RecordError(err)
		readCommitMessageSpan.End()
		return nil
	}

	message := string(content)
	rules := messageCommentRules(ctx, message)

	// A trailer prepare already stamped is kept (e.g. amend); inherited ones are links
	if existingCpID, found := stampedTrailer(ctx, message, rules, inherited); found {
		readCommitMessageSpan.End()
		// Trailer already exists (e.g., amend) - keep it
		logging.Debug(logCtx, "prepare-commit-msg: trailer already exists",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
			slog.String("existing_checkpoint_id", existingCpID.String()),
		)
		recordStampedTrailer(ctx, existingCpID)
		return nil
	}
	readCommitMessageSpan.End()

	// Resolve the checkpoint ID and session metadata.
	_, resolveMetadataSpan := perf.Start(ctx, "resolve_session_metadata")
	checkpointID, err := checkpointIDForSessions(ctx, sessionsWithContent)
	if err != nil {
		resolveMetadataSpan.RecordError(err)
		resolveMetadataSpan.End()
		return fmt.Errorf("failed to generate checkpoint ID: %w", err)
	}

	agentType, displayPrompt, commitLinking := s.trailerPromptContext(ctx, sessionsWithContent)
	resolveMetadataSpan.End()

	// Add trailer differently based on commit source
	// NOTE: TTY confirmation (askConfirmTTY) is intentionally NOT wrapped in a span
	// because it blocks on user input and would skew timing.
	switch source {
	case commitSourceMessage:
		// Using -m or -F: behavior depends on TTY availability and commit_linking setting
		switch {
		case !interactive.CanPromptInteractively():
			// No TTY (agent subprocess, CI) — auto-link without prompting
			message = addCheckpointTrailerAboveComments(message, checkpointID, rules)
		case commitLinking == settings.CommitLinkingAlways:
			// User previously chose "always" — auto-link without prompting
			message = addCheckpointTrailerAboveComments(message, checkpointID, rules)
		default:
			// Human at terminal — prompt interactively
			header := "Entire: Active " + string(agentType) + " session detected"
			var details []string
			if displayPrompt != "" {
				details = append(details, "Last prompt: "+displayPrompt)
			}

			logging.Info(logCtx, CommitLinkingPromptLogMsg,
				slog.String("strategy", "manual-commit"),
				slog.String("source", source),
			)
			result := askConfirmTTY(header, details, "Link this commit to session context?", true)
			if result == ttyResultSkip {
				logging.Debug(logCtx, "prepare-commit-msg: user declined trailer",
					slog.String("strategy", "manual-commit"),
					slog.String("source", source),
				)
				return nil
			}
			if result == ttyResultLinkAlways {
				// Persist preference so future commits auto-link (non-fatal if it fails)
				if saveErr := saveCommitLinkingAlways(ctx); saveErr != nil {
					logging.Warn(logCtx, "prepare-commit-msg: failed to save commit_linking=always",
						slog.String("error", saveErr.Error()),
					)
				}
			}
			message = addCheckpointTrailerAboveComments(message, checkpointID, rules)
		}
	default:
		if rules.edited && !blockEndsCommit(strings.Split(message, "\n"), rules) {
			// Normal editor flow: add trailer with explanatory comment (will be stripped by git)
			message = addCheckpointTrailerWithComment(message, checkpointID, string(agentType), displayPrompt, rules.prefix)
		} else {
			// --no-edit, or a trailer that must follow git's kept block: the
			// explanation, above the trailer, would be recorded with the block
			message = addCheckpointTrailerAboveComments(message, checkpointID, rules)
		}
	}

	logging.Info(logCtx, "prepare-commit-msg: trailer added",
		slog.String("strategy", "manual-commit"),
		slog.String("source", source),
		slog.String("checkpoint_id", checkpointID.String()),
	)

	// Write updated message back
	_, writeCommitMessageSpan := perf.Start(ctx, "write_commit_message")
	if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil { //nolint:gosec // path from git hook arg
		writeCommitMessageSpan.RecordError(err)
		writeCommitMessageSpan.End()
		return nil
	}
	writeCommitMessageSpan.End()
	recordStampedTrailer(ctx, checkpointID)

	return nil
}

// trailerPromptContext returns what the trailer prompt shows and whether to
// ask: the first session's agent type and display-ready last prompt, and the
// commit_linking setting.
func (s *ManualCommitStrategy) trailerPromptContext(ctx context.Context, sessions []*SessionState) (types.AgentType, string, string) {
	var agentType types.AgentType
	var lastPrompt string
	if len(sessions) > 0 {
		firstSession := sessions[0]
		if firstSession.AgentType != "" {
			agentType = firstSession.AgentType
		}
		lastPrompt = s.getLastPrompt(ctx, firstSession)
	}

	// Prepare prompt for display: collapse newlines/whitespace, then truncate (rune-safe)
	displayPrompt := stringutil.TruncateRunes(stringutil.CollapseWhitespace(lastPrompt), 80, "...")

	// Load commit_linking setting to decide whether to prompt
	commitLinking := settings.CommitLinkingPrompt // safe default
	if stngs, loadErr := settings.Load(ctx); loadErr == nil {
		commitLinking = stngs.GetCommitLinking()
	}
	return agentType, displayPrompt, commitLinking
}

// openRepositoryTimed opens the repository under an "open_repository" perf span.
func openRepositoryTimed(ctx context.Context) (*git.Repository, error) {
	_, span := perf.Start(ctx, "open_repository")
	defer span.End()
	repo, err := OpenRepository(ctx)
	if err != nil {
		span.RecordError(err)
		return nil, err
	}
	return repo, nil
}

// inheritSquashedCheckpointTrailers handles a commit made while `git merge
// --squash` is in progress (SQUASH_MSG present): the squashed commits'
// Entire-Checkpoint trailers are carried into the message when a staged path is
// one the recorded commits changed. `commit -m` reports source "message", not "squash", so this runs
// before the source switch — but only for those two sources: an amend must
// keep its own logic even when an abandoned squash left SQUASH_MSG behind.
// Returns the inherited IDs; nil when there are none or the message is
// unusable. Ordinary matching runs afterwards either way.
func (s *ManualCommitStrategy) inheritSquashedCheckpointTrailers(ctx context.Context, commitMsgFile, source string) []id.CheckpointID {
	if source != commitSourceMessage && source != "squash" {
		return nil
	}
	logCtx := logging.WithComponent(ctx, "checkpoint")
	gitDir, err := GetGitDir(ctx)
	if err != nil {
		return nil
	}
	// SQUASH_MSG lives in the PER-WORKTREE git dir, like the sequencer markers.
	// The root is the shared registry handle (gitdir.OpenAt): never close it.
	root, err := gitdir.OpenAt(gitDir)
	if err != nil {
		return nil
	}
	squashMsg, err := osroot.ReadFileNoFollow(root, "SQUASH_MSG")
	if err != nil {
		return nil // no squash in progress (or unreadable: fall through to normal matching)
	}

	inherited := withoutDeletedCheckpoints(ctx, trailers.ParseAllCheckpoints(string(squashMsg)))
	if len(inherited) == 0 {
		return nil
	}
	repo, err := OpenRepository(ctx)
	if err != nil {
		return nil
	}
	defer repo.Close()
	if !squashTouchesStagedPath(ctx, repo, squashMsg) {
		stripInheritedCheckpointTrailers(commitMsgFile, inherited)
		logging.Debug(logCtx, "prepare-commit-msg: ignored stale squash message whose commits changed none of the staged paths",
			slog.String("source", source),
			slog.Int("inherited", len(inherited)))
		return nil
	}
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		return nil // nothing inherited; let ordinary matching report its own failure
	}
	message := string(content)
	present := make(map[string]bool)
	for _, cpID := range trailers.ParseAllCheckpoints(message) {
		present[cpID.String()] = true
	}
	rules := messageCommentRules(ctx, message)
	added := 0
	for _, cpID := range inherited {
		if present[cpID.String()] {
			continue
		}
		message = addCheckpointTrailerAboveComments(message, cpID, rules)
		added++
	}
	if added == 0 {
		logging.Debug(logCtx, "prepare-commit-msg: squash in progress, message already carries the squashed trailers",
			slog.String("source", source),
			slog.Int("inherited", len(inherited)))
		return inherited
	}
	if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil { //nolint:gosec // path from git hook arg
		return nil // nothing landed; hooks stay silent, ordinary matching may still try
	}
	logging.Info(logCtx, "prepare-commit-msg: inherited checkpoint trailers from the squashed commits",
		slog.String("strategy", "manual-commit"),
		slog.String("source", source),
		slog.Int("inherited", len(inherited)),
		slog.Int("added", added))
	return inherited
}

// squashTouchesStagedPath reports whether a staged path is one that a
// commit Git recorded in SQUASH_MSG changed. Git leaves SQUASH_MSG behind when a
// squash is abandoned, so the file alone is not proof that the current staged
// work belongs to those commits; matching paths rather than content keeps a
// squash whose files were touched up before committing.

	// Don't add if prepare already stamped one (inherited trailers are links)
	if existingCpID, found := stampedTrailer(logCtx, message, rules, inherited); found {
		recordStampedTrailer(logCtx, existingCpID)
		return nil
	}

	message = addCheckpointTrailerAboveComments(message, cpID, rules)

	logging.Info(logCtx, "prepare-commit-msg: agent commit trailer added",
		slog.String("strategy", "manual-commit"),
		slog.String("source", source),
		slog.String("checkpoint_id", cpID.String()),
		slog.String("session_id", state.SessionID),
	)

	if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil { //nolint:gosec // path from git hook arg
		return nil //nolint:nilerr // Hook must be silent on failure
	}
	recordStampedTrailer(logCtx, cpID)
	return nil
}

func checkpointIDForSessions(ctx context.Context, states []*SessionState) (id.CheckpointID, error) {
	for _, state := range states {
		if checkpointID := state.PendingCondensationID(); checkpointID != id.EmptyCheckpointID {
			return checkpointID, nil
		}
	}
	checkpointID, err := checkpoint.GenerateCheckpointID(ctx)
	if err != nil {
		return id.EmptyCheckpointID, fmt.Errorf("generate checkpoint ID: %w", err)
	}
	return checkpointID, nil
}

// addCheckpointTrailer adds the Entire-Checkpoint trailer to a commit message.
// Delegates to trailers.AppendCheckpointTrailer for trailer-aware formatting.
func addCheckpointTrailer(message string, checkpointID id.CheckpointID) string {
	return trailers.AppendCheckpointTrailer(message, checkpointID.String())
}

// commitSourceMessage is prepare-commit-msg's source for `-m`/`-F` messages.
const commitSourceMessage = "message"

// gitOpensEditor reports whether git opens the commit message in the editor,
// which git tells its commit hooks: it runs them with GIT_EDITOR=: when it
// does not (githooks(5)), as for -m/-F without -e, --no-edit and -C. The
// source word cannot tell: -m with -e, and an amend with --no-edit or without.
func gitOpensEditor() bool {
	return os.Getenv("GIT_EDITOR") != ":"
}

// commentRules is how git treats comment lines in a message
// prepare-commit-msg was handed. prefix starts the comment lines git's cleanup
// sees. trailerPrefix starts the ones git's trailer grammar skips once the
// commit is recorded, as post-commit and attach read it; they differ only for
// core.commentChar=auto. edited means git opens the message in the editor,
// and has appended its comment block unless commit.status is off. stripped
// means git's cleanup drops every comment line; otherwise git keeps them.
type commentRules struct {
	prefix        string
	trailerPrefix string
	edited        bool
	stripped      bool
}

// messageCommentRules returns how git treats comment lines in the message
// prepare-commit-msg was handed.
func messageCommentRules(ctx context.Context, message string) commentRules {
	cfg := gitCommentConfig(ctx)
	edited := gitOpensEditor()
	return commentRules{
		prefix:        cfg.prefixFor(message, edited),
		trailerPrefix: cfg.trailerPrefix(),
		edited:        edited,
		stripped:      cfg.dropsComments(edited),
	}
}

// recordedCommentPrefix returns the prefix git's trailer grammar skips in a
// recorded commit message (see commentConfig.trailerPrefix).
func recordedCommentPrefix(ctx context.Context) string {
	return gitCommentConfig(ctx).trailerPrefix()
}

// autoCommentChar is the core.commentChar value that lets `git commit` pick
// the prefix.
const autoCommentChar = "auto"

// commentConfig is what git's config says about comment lines in a commit
// message.
type commentConfig struct {
	prefix  string // core.commentChar or core.commentString (aliases; the last one set wins), else git's default
	cleanup string // commit.cleanup, "" when unset
	status  bool   // commit.status: git writes its comment block into a message it opens in the editor
}

// commentConfigKey holds a commit hook's comment config (withCommentConfig).
type commentConfigKey struct{}

type commentConfigSnapshot struct {
	once sync.Once
	cfg  commentConfig
}

// withCommentConfig gives a commit hook one read of commentConfig, on first
// use: prepare-commit-msg's squash, redo, amend and stamping steps each need it.
func withCommentConfig(ctx context.Context) context.Context {
	if _, ok := ctx.Value(commentConfigKey{}).(*commentConfigSnapshot); ok {
		return ctx
	}
	return context.WithValue(ctx, commentConfigKey{}, &commentConfigSnapshot{})
}

// gitCommentConfig returns the hook's commentConfig snapshot, reading it on
// first use; without one (a caller outside a commit hook) it reads every time.
func gitCommentConfig(ctx context.Context) commentConfig {
	snap, ok := ctx.Value(commentConfigKey{}).(*commentConfigSnapshot)
	if !ok {
		return readGitCommentConfig(ctx)
	}
	snap.once.Do(func() { snap.cfg = readGitCommentConfig(ctx) })
	return snap.cfg
}

// readGitCommentConfig reads commentConfig in one git config call.
func readGitCommentConfig(ctx context.Context) commentConfig {
	cfg := commentConfig{prefix: trailers.DefaultCommentPrefix, status: true}
	out, err := exec.CommandContext(ctx, "git", "config", "--get-regexp", `^(core\.comment(char|string)|commit\.(cleanup|status))$`).Output()
	if err != nil {
		return cfg // unset, or unreadable
	}
	for _, line := range strings.Split(strings.TrimRight(string(out), "\n"), "\n") {
		key, value, _ := strings.Cut(line, " ")
		switch {
		case key == "commit.cleanup":
			cfg.cleanup = value
		case key == "commit.status":
			cfg.status = !slices.Contains([]string{"false", "no", "off", "0"}, strings.ToLower(value))
		case value == "":
			cfg.prefix = trailers.DefaultCommentPrefix
		default:
			cfg.prefix = value
		}
	}
	return cfg
}

// prefixFor returns the prefix git cleans message with. For "auto" git picks
// it from the message (see trailers.AutoCommentPrefix), and writes its comment
// block with it only into a message it opens in the editor (edited) while
// commit.status is on.
func (cfg commentConfig) prefixFor(message string, edited bool) string {
	if cfg.prefix != autoCommentChar {
		return cfg.prefix
	}
	return trailers.AutoCommentPrefix(message, edited && cfg.status)
}

// trailerPrefix returns the prefix git's trailer grammar skips in a recorded
// commit message. Only `git commit` resolves "auto"; `git interpret-trailers`
// reads it as git's default.
func (cfg commentConfig) trailerPrefix() string {
	if cfg.prefix == autoCommentChar {
		return trailers.DefaultCommentPrefix
	}
	return cfg.prefix
}

// cleanupStrip is the commit.cleanup mode that drops comment lines from every
// message, not only an edited one.
const cleanupStrip = "strip"

// dropsComments reports whether git's cleanup drops comment lines from a
// message: always under commit.cleanup=strip, never under whitespace, verbatim
// or scissors, and by default only from one it opened in the editor.
func (cfg commentConfig) dropsComments(edited bool) bool {
	switch cfg.cleanup {
	case cleanupStrip:
		return true
	case "whitespace", "verbatim", "scissors":
		return false
	}
	return edited
}

// blockEndsCommit reports whether lines of git's comment block would stay in
// the recorded commit below a trailer placed above the block, where the
// trailer grammar does not skip them: a cleanup mode that keeps comment lines,
// core.commentChar=auto picking a prefix other than the grammar's, and a block
// that starts above any scissors line.
func blockEndsCommit(lines []string, rules commentRules) bool {
	if rules.stripped || rules.prefix == rules.trailerPrefix {
		return false
	}
	start := trailers.EditorCommentBlockStart(lines, rules.prefix)
	return start >= 0 && start != trailers.ScissorsLineIndex(lines, rules.prefix)
}

// trailerLine returns the line of message a trailer goes above, or -1 when it
// is appended: git's comment block (see trailers.EditorCommentBlockStart), so
// `commit -v` cannot cut the trailer off with the diff, unless the block would
// then end the recorded commit (blockEndsCommit), when the trailer goes below
// it, above any scissors line. A message git does not open in the editor has
// no block and keeps its comment lines as written; git's trailer grammar skips
// comment lines that end a message.
func trailerLine(lines []string, rules commentRules) int {
	switch {
	case !rules.edited:
		return -1
	case blockEndsCommit(lines, rules):
		return trailers.ScissorsLineIndex(lines, rules.prefix)
	}
	return trailers.EditorCommentBlockStart(lines, rules.prefix)
}

// addCheckpointTrailerAboveComments adds a trailer where trailerLine places it.
func addCheckpointTrailerAboveComments(message string, checkpointID id.CheckpointID, rules commentRules) string {
	lines := strings.Split(message, "\n")
	if i := trailerLine(lines, rules); i >= 0 {
		head := strings.TrimRight(addCheckpointTrailer(strings.Join(lines[:i], "\n"), checkpointID), "\n")
		return head + "\n\n" + strings.Join(lines[i:], "\n")
	}
	return addCheckpointTrailer(message, checkpointID)
}

// trailerExplanation starts the comment prepare-commit-msg writes above an
// editor message's trailer; commit-msg reads it as the message being an editor
// one even when no git comment block follows (commit.status=false).
const trailerExplanation = " Remove the Entire-Checkpoint trailer below if you don't want to link this commit to "

// addCheckpointTrailerWithComment adds the Entire-Checkpoint trailer to an editor message
// above git's comment block, with a comment above the trailer explaining that the user can
// remove it if they don't want to link the commit to the agent session. If prompt is
// non-empty, it's shown as context. The comment is written with commentPrefix, the prefix git
// strips (see messageCommentRules). The comment and the trailer are separate paragraphs below the
// user's lines: a line typed just above the trailer would otherwise join the subject
// paragraph, which git never reads as trailers, and cleanup modes that keep comment lines
// would leave the comment inside the trailer block.
func addCheckpointTrailerWithComment(message string, checkpointID id.CheckpointID, agentName, prompt, commentPrefix string) string {
	trailer := trailers.CheckpointTrailerKey + ": " + checkpointID.String()
	commentLines := []string{
		commentPrefix + trailerExplanation + agentName + " session context.",
	}
	if prompt != "" {
		commentLines = append(commentLines, commentPrefix+" Last Prompt: "+prompt)
	}
	commentLines = append(commentLines, commentPrefix+" The trailer will be added to your next commit based on this branch.")
	comment := strings.Join(commentLines, "\n")

	lines := strings.Split(message, "\n")
	commentStart := trailers.EditorCommentBlockStart(lines, commentPrefix)
	if commentStart == -1 {
		// No git comments (commit.status=false): comment and trailer go last
		return strings.TrimRight(message, "\n") + "\n\n" + comment + "\n\n" + trailer + "\n"
	}

	// Split into user content and git comments
	userContent := strings.Join(lines[:commentStart], "\n")
	gitComments := strings.Join(lines[commentStart:], "\n")

	// Build result: user content, comment, trailer, git comments, a blank line between each
	userContent = strings.TrimRight(userContent, "\n")
	if userContent == "" {
		// No user content yet - leave space for them to type
		// Two newlines: first for user's message line, second for blank separator
		return "\n\n" + comment + "\n\n" + trailer + "\n\n" + gitComments
	}
	return userContent + "\n\n" + comment + "\n\n" + trailer + "\n\n" + gitComments
}

// resolveSessionAgentType picks the most reliable identifier for which agent
// owns a session, given the agent whose hook is firing right now (callerAgentType),
// an optional transcript path, and the SessionStart hint stored under the
// session ID.
//
// Priority (strongest signal wins):
//  1. Transcript path — when transcriptPath is inside a registered agent's
//     GetSessionDir(repoRoot), the file's location is direct evidence.
//  2. SessionStart hint — first agent to fire SessionStart for this session.
//     Useful when transcriptPath is empty (e.g., Claude Code's first TurnStart
//     in a forwarded-hook scenario).
//  3. callerAgentType — the agent whose hook called us. Used when no stronger
//     signal exists.
func resolveSessionAgentType(ctx context.Context, sessionID string, callerAgentType types.AgentType, transcriptPath string) types.AgentType {
	if repoRoot, err := paths.WorktreeRoot(ctx); err == nil && transcriptPath != "" {
		if owner, ok := agent.AgentForTranscriptPath(transcriptPath, repoRoot); ok {
			return owner.Type()
		}
	}
	if hint := LoadAgentTypeHint(ctx, sessionID); hint != "" && hint != agent.AgentTypeUnknown {
		return hint
	}
	return callerAgentType
}

// correctSessionAgentType returns the agent type that owns transcriptPath when
// it disagrees with currentType. Returns (currentType, false) if there's no
// disagreement or no transcript signal — callers should treat that as a no-op.
//
// Used to repair sessions whose AgentType was set incorrectly on an earlier
// turn (e.g., a wrapper agent's hook fired first before the real agent's
// transcript path was available). Only the transcript path is considered;
// the SessionStart hint is intentionally ignored here because it can also be
// the wrong-first-writer that we're trying to correct.
func correctSessionAgentType(ctx context.Context, currentType types.AgentType, transcriptPath string) (types.AgentType, bool) {
	if transcriptPath == "" {
		return currentType, false
	}
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return currentType, false
	}
	owner, ok := agent.AgentForTranscriptPath(transcriptPath, repoRoot)
	if !ok {
		return currentType, false
	}
	if owner.Type() == currentType {
		return currentType, false
	}
	return owner.Type(), true

