// isGitSequenceOperation checks if git is currently in the middle of a rebase,
// cherry-pick, or revert operation. During these operations, commits are being
// replayed and should not be linked to agent sessions.
//
// Detects:
//   - rebase: .git/rebase-merge/ or .git/rebase-apply/ directories
//   - cherry-pick: .git/CHERRY_PICK_HEAD file
//   - revert: .git/REVERT_HEAD file
func isGitSequenceOperation(ctx context.Context) bool {
	// Get git directory (handles worktrees and relative paths correctly)
	gitDir, err := GetGitDir(ctx)
	if err != nil {
		return false // Can't determine, assume not in sequence operation
	}

	// These markers live in the PER-WORKTREE git dir, not the common dir, which
	// is why this opens gitDir rather than using gitdir.Open.
	root, err := gitdir.OpenAt(gitDir)
	if err != nil {
		return false // Can't determine, assume not in sequence operation
	}

	// Check for rebase state directories, then cherry-pick and revert state files.
	for _, marker := range []string{"rebase-merge", "rebase-apply", "CHERRY_PICK_HEAD", "REVERT_HEAD"} {
		if _, err := root.Lstat(marker); err == nil {
			return true
		}
	}

	return false
}

// GitOperationInProgress names the git operation the worktree is in the middle
// of (rebase or am, cherry-pick, revert, merge, bisect), or returns "" when
// none is. A command about to move a branch must not do so mid-operation. A
// git dir that can't be read reports none, as isGitSequenceOperation does.
func GitOperationInProgress(ctx context.Context) string {
	gitDir, err := GetGitDir(ctx)
	if err != nil {
		return ""
	}
	// Per-worktree markers; see isGitSequenceOperation.
	root, err := gitdir.OpenAt(gitDir)
	if err != nil {
		return ""
	}
	for _, m := range []struct{ marker, op string }{
		{"rebase-merge", "a rebase"},
		{"rebase-apply", "a rebase or am"},
		{"CHERRY_PICK_HEAD", "a cherry-pick"},
		{"REVERT_HEAD", "a revert"},
		{"MERGE_HEAD", "a merge"},
		{"BISECT_LOG", "a bisect"},
	} {
		if _, err := root.Lstat(m.marker); err == nil {
			return m.op
		}
	}
	return ""
}

